SELECT QUARTER(s.started_at) AS started_quarter, CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END AS started_cohort, MAX(we.event_time) AS latest_event_time FROM web_events we INNER JOIN sessions s ON we.session_id = s.id WHERE HOUR(s.started_at) BETWEEN 9 AND 16 GROUP BY QUARTER(s.started_at), CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END;
